from scipy.special import erf
lab=np.load('feats/y.npy')
gelu=lambda x: 0.5*x*(1+erf(x/np.sqrt(2)))
def lnorm(X): X=X-X.mean(1,keepdims=True); return X/np.sqrt((X**2).mean(1,keepdims=True)+1e-12)
def mkfolds(seed):
    rng=np.random.default_rng(seed); fo=np.zeros(len(lab),int)
    for c in range(8):
        idx=np.where(lab==c)[0]; rng.shuffle(idx); fo[idx]=np.arange(len(idx))%5
    return fo
FO=[np.load('feats/folds.npy'),mkfolds(7),mkfolds(8)]
def run(E,lams,a=2,t=0,rho=1.0):
    R=np.sqrt(E.shape[1]); res={l:[] for l in lams}
    for fo in FO:
        FS=[]
        for f in range(5):
            tr=fo!=f; mu=E[tr].mean(0); sd=E[tr].std(0)+1e-6
            Z=(E-mu)/sd; C=Z[tr]/np.linalg.norm(Z[tr],axis=1,keepdims=True)
            FS.append(np.concatenate([gelu(a*(Z@C.T)/R+t), rho*Z/R],1))
        for lam in lams:
            pr=np.zeros(len(lab),int)
            for f in range(5):
                tr=fo!=f; te=~tr; F=FS[f]; Ftr=F[tr]; m=Ftr.mean(0); Y=np.eye(8)[lab[tr]]-1/8
                Wt=np.linalg.solve((Ftr-m).T@(Ftr-m)+lam*np.eye(F.shape[1]),(Ftr-m).T@Y)
                pr[te]=((F[te]-m)@Wt).argmax(1)
            res[lam].append((pr==lab).mean())
    return {l:round(np.mean(v),4) for l,v in res.items()}
